SELECT CASE WHEN suppliers.rating >= 3.9 THEN 'high' WHEN suppliers.rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(inventory.quantity) - MIN(inventory.quantity) AS quantity_range FROM inventory INNER JOIN products ON inventory.product_id = products.id INNER JOIN suppliers ON products.supplier_id = suppliers.id WHERE products.product_name LIKE '%Nois%' GROUP BY CASE WHEN suppliers.rating >= 3.9 THEN 'high' WHEN suppliers.rating >= 2.1 THEN 'mid' ELSE 'low' END HAVING quantity_range >= 26 ORDER BY 1 ASC, quantity_range ASC;
